definition.script:
pipeline {
  agent any
  options { timestamps(); timeout(time: 3, unit: 'MINUTES'); buildDiscarder(logRotator(numToKeepStr: '50', artifactNumToKeepStr: '50')) }
  stages {
    stage('Resolve commit') {
      steps {
        // 只读：SHA/REPO 由 Jenkins 以环境变量传入，脚本内先校验再使用；不 build、不 docker、不 kubectl
        sh '''
          set -uo pipefail
          bash /jenkins-backup/scripts/resolve-commit.sh
        '''
      }
    }
  }
  post {
    always {
      script {
        if (fileExists('resolve.desc')) {
          currentBuild.description = readFile('resolve.desc').trim()
        }
      }
      archiveArtifacts artifacts: 'resolve.json', allowEmptyArchive: true
    }
  }
}
